81	// requireParentMidSecondHandover 校验第二次交接待确认期间原样的当前状态：
82	// 李四在实验室B持有剩余 6.750，待确认详情指向 TR-002。
83	func requireParentMidSecondHandover(t *testing.T, p *Sample, hAt2 time.Time) {
